import sys
from collections import deque

def add_edge(grid, g, i, j, s, t):
    n = len(grid) - 1
    m = len(grid[0]) - 1
    if s <= 0 or t <= 0 or s > n or t > m:
        return
    g[grid[i][j]].append(grid[s][t])

def hopcroft_karp(g, m, n):
    pair_u = [0] * (m + 1)
    pair_v = [0] * (n + 1)
    dist = [0] * (m + 1)
    result = 0

    def bfs():
        queue = deque()
        for u in range(1, m + 1):
            if pair_u[u] == 0:
                dist[u] = 0
                queue.append(u)
            else:
                dist[u] = float('inf')
        max_dist = float('inf')
        while queue:
            u = queue.popleft()
            if dist[u] < max_dist:
                for v in g[u]:
                    if pair_v[v] == 0:
                        max_dist = dist[u] + 1
                    elif dist[pair_v[v]] == float('inf'):
                        dist[pair_v[v]] = dist[u] + 1
                        queue.append(pair_v[v])
        return max_dist != float('inf')

    def dfs(u):
        if u != 0:
            for v in g[u]:
                if pair_v[v] == 0 or (dist[pair_v[v]] == dist[u] + 1 and dfs(pair_v[v])):
                    pair_u[u] = v
                    pair_v[v] = u
                    return True
            dist[u] = float('inf')
            return False
        return True

    while bfs():
        for u in range(1, m + 1):
            if pair_u[u] == 0 and dfs(u):
                result += 1
    return result

def main():
    input_line = sys.stdin.readline().strip()
    parts = input_line.split()
    n = int(parts[0])
    m = int(parts[1])
    total = 0

    if n > 100:
        remN = (n - 100) % 6
        qN = (n - 100) // 6
        total += qN * 6 * m
        n = 100 + remN

    if m > 100:
        remM = (m - 100) % 6
        qM = (m - 100) // 6
        total += qM * 6 * n
        m = 100 + remM

    grid = [[0] * (m + 1) for _ in range(n + 1)]
    u_label = 1
    v_label = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i + j) % 2 == 0:
                grid[i][j] = u_label
                u_label += 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i + j) % 2 != 0:
                grid[i][j] = v_label
                v_label += 1

    adj = [[] for _ in range(u_label)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i + j) % 2 == 0:
                add_edge(grid, adj, i, j, i - 3, j)
                add_edge(grid, adj, i, j, i - 2, j - 1)
                add_edge(grid, adj, i, j, i - 2, j + 1)
                add_edge(grid, adj, i, j, i, j - 3)
                add_edge(grid, adj, i, j, i - 1, j - 2)
                add_edge(grid, adj, i, j, i + 1, j - 2)
                add_edge(grid, adj, i, j, i, j + 3)
                add_edge(grid, adj, i, j, i - 1, j + 2)
                add_edge(grid, adj, i, j, i + 1, j + 2)
                add_edge(grid, adj, i, j, i + 3, j)
                add_edge(grid, adj, i, j, i + 2, j - 1)
                add_edge(grid, adj, i, j, i + 2, j + 1)

    max_match = hopcroft_karp(adj, u_label - 1, v_label - 1)
    total += 2 * max_match
    print(total)

if __name__ == "__main__":
    main()

